import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { DATE, settingsKey, useSettings } from './settings';
import type { Settings } from './settings';
import { useOneAtATime } from '../../query/useOneAtATime';

type DelegationForm = { user: string; from: string; to: string };

const EMPTY: DelegationForm = { user: '', from: '', to: '' };

// The steward role delegated on the sheet and the form a steward delegates it with (blank dates: the sheet's today).
export function Delegations() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const delegations = useSettings().data?.delegations ?? [];
  const [form, setForm] = useState<DelegationForm>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const save = useMutation({
    mutationFn: (input: DelegationForm) =>
      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/delegations?user=${encodeURIComponent(user)}`, input),
    onSuccess: async (saved) => {
      setForm(EMPTY);
      setError('');
      queryClient.setQueryData(settingsKey(sheet), saved);
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet) });
    },
    onError: () => setError('That delegation was refused: only a steward delegates, and the to-date is not before the from-date.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const name = form.user.trim();
    const from = form.from.trim();
    const to = form.to.trim();
    if (name === '') {
      setError('Type a user name.');
      return;
    }
    if ((from !== '' && !DATE.test(from)) || (to !== '' && !DATE.test(to))) {
      setError('Type the dates as yyyy-mm-dd, or leave them blank for the sheet\'s today.');
      return;
    }
    if (from !== '' && to !== '' && to < from) {
      setError('The to-date cannot be before the from-date.');
      return;
    }
    once(() => save.mutateAsync({ user: name, from, to }));
  };

  const change = (patch: Partial<DelegationForm>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  return (
    <section data-testid="delegations">
      <ul data-testid="delegate-list">
        {delegations.map((d, i) => (
          <li key={i} data-testid="delegate-line">
            {d.by} delegated steward to {d.user} from {d.from} to {d.to}
          </li>
        ))}
      </ul>
      <form onSubmit={submit} data-testid="delegate-form">
        <input
          data-testid="delegate-user"
          placeholder="User name"
          value={form.user}
          onChange={(e) => change({ user: e.target.value })}
        />
        <input
          data-testid="delegate-from"
          placeholder="From (yyyy-mm-dd; blank: today)"
          value={form.from}
          onChange={(e) => change({ from: e.target.value })}
        />
        <input
          data-testid="delegate-to"
          placeholder="To (yyyy-mm-dd; blank: today)"
          value={form.to}
          onChange={(e) => change({ to: e.target.value })}
        />
        <button type="submit" data-testid="delegate-submit" disabled={save.isPending}>
          Delegate steward
        </button>
        {error && <span data-testid="delegate-error">{error}</span>}
      </form>
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** That `user` watches the person `personId`. */
export type Watch = { personId: number; user: string };

/** The query key for the sheet's watches; under sheetKey, so re-loading the sheet re-reads them. */
export const watchesKey = (sheet: string) => [...sheetKey(sheet), 'watches'] as const;

/** Every watch on the sheet, in the order they started. */
export function useWatches() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: watchesKey(sheet),
    queryFn: () => getJson<Watch[]>(`/api/sheets/${encodeURIComponent(sheet)}/watches`),
    enabled: !!sheet,
  });
}

/** Whether `user` watches the person. */
export const isWatching = (watches: Watch[], personId: number, user: string) =>
  watches.some((w) => w.personId === personId && w.user === user);
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { PersonWatch } from './PersonWatch';

export const contributions = [
  PersonColumnHeads.fill({ order: 19.8, Component: () => <th>Watched</th> }),
  PersonColumns.fill({ order: 19.8, Component: PersonWatch }),
];
import { defineSlot } from '../Slot';

/** The home page's body: each feature on the one screen contributes its own panel. */
export const HomeMain = defineSlot('home.main');
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` tells a refusal (400) from a conflict with someone else's save (409). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/**
 * The date this screen shows the sheet as of (yyyy-MM-dd), or '' when it shows the sheet now. It is
 * the `asof` search param (features/session/AsOf), read here so every read of the sheet carries it
 * and every change is refused while it is set.
 */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return raw.replace(/^"(.*)"$/, '$1');
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // A screen showing the sheet as of a date changes nothing; loading a sheet is not a change.
  if (init?.method && init.method !== 'GET' && path !== '/api/sheets' && currentAsOf()) {
    throw new HttpError(`${init.method} ${path} refused: the sheet is shown as of ${currentAsOf()}`, 400);
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  const asOf = currentAsOf();
  if (asOf && path.startsWith('/api/sheets/')) {
    return send<T>(`${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`);
  }
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { covers, liveHolds } from '../people/people';
import type { Hold } from '../people/people';
import { sheetKey, useCurrentSheet } from '../session/session';

/**
 * Where a claim is in its life: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit makes it
 * PENDING, which a steward approves (SETTLED) or rejects (OPEN); DRAFT, OPEN or PENDING -> VOID.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** Whether a claim is open: OPEN, or PENDING (handled like an open claim). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * Whether a claim is deferred on the sheet's `today`: OPEN, deferred until a date after it. A deferred claim counts
 * in no total, is not overdue, cannot be settled and is left unbound by a statement.
 */
export const deferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== null && today !== '' && today < c.deferredUntil;

/** Whether a statement binds the claim now: it was stated and is not PENDING (a pending claim shows its live figure). */
export const bound = (c: Claim) => c.stated && c.status !== 'PENDING';

/**
 * A claim as the store holds it: the amount with two decimals, the date as yyyy-MM-dd; its number
 * is the sheet's next one when it was opened (1, 2, ...; under period numbering, the next within its period (the one containing its due-by): P1-1, X-1), null while a draft (a voided claim keeps it); its due is the
 * one fixed when it was settled (two decimals), null while it is live; openedBy is the user who
 * opened it, null while a draft; stated is whether its person's last statement bound it to a figure,
 * statedDue that figure (two decimals; null: n/a) — it then shows and totals that, not its live figure;
 * corrects is, for a correction (a negative amount), the number of the settled claim it corrects, null otherwise;
 * dueBy (yyyy-MM-dd) is fixed when it was created: its date plus the terms of its person's grade in force on it;
 * log is its status log, oldest first: each status it has had, the user who gave it, the sheet's today then and its due then;
 * deferredUntil (yyyy-MM-dd) is the date it was deferred until, null when it never was;
 * proofs is how many proofs it has been given (a claim whose due is above the proof threshold in force on its date is
 * settled or approved only once it has one);
 * splitFrom is the number of the claim it was split off, null when it was not split off one;
 * lockedBy is the user whose open editor locks it for every other user, null when it is not locked;
 * lateEntry is whether it was added while the period containing its due-by was soft-closed;
 * reminded (yyyy-MM-dd) is the last day a reminder was written for it, null when it never was.
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: ClaimLogLine[];
  deferredUntil: string | null;
  proofs: number;
  splitFrom: string | null;
  lockedBy: string | null;
  lateEntry: boolean;
  reminded: string | null;
};

/** A line of a claim's status log: the status, the user, the sheet's today (yyyy-MM-dd) and the due then (two decimals, or n/a). */
export type ClaimLogLine = { status: ClaimStatus; by: string; date: string; due: string };

/**
 * Whether a claim counts toward claimed, due-total and every live total: only OPEN, PENDING and SETTLED do,
 * and an open (or pending) one not when one of its person's `holds` covers its date and no statement binds it,
 * nor while it is deferred on the sheet's `today`.
 */
export const counts = (c: Claim, holds: Hold[], today: string) =>
  c.status === 'SETTLED' ||
  (isOpen(c) && !deferred(c, today) && (bound(c) || !holds.some((h) => covers(h, c.date))));

/** Each person's live holds on the sheet's `today`, by id: their open claims dated within one count in no live total. */
export const holdsById = (people: { id: number; holds: Hold[]; retiredFrom: string | null }[], today: string) =>
  new Map(people.map((p) => [p.id, liveHolds(p, today)]));

